module fsm #(
    parameter s0 = 3'b000,
    parameter s1 = 3'b001,
    parameter s2 = 3'b010,
    parameter s3 = 3'b011,
    parameter s4 = 3'b100,
    parameter s5 = 3'b101
) (
    input IN,
    output reg MATCH,
    input CLK,
    input RST
);

parameter S0 = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
parameter S5 = 3'b101;

reg [2:0] ST_cr, ST_nr;

always @* begin
    case (ST_cr)
        S0: begin
            if (IN == 1) ST_nr = S1;
            else ST_nr = S0;
        end
        S1: begin
            if (IN == 1) ST_nr = S1;
            else ST_nr = S2;
        end
        S2: begin
            if (IN == 1) ST_nr = S1;
            else ST_nr = S3;
        end
        S3: begin
            if (IN == 1) ST_nr = S4;
            else ST_nr = S0;
        end
        S4: begin
            if (IN == 1) ST_nr = S5;
            else ST_nr = S2;
        end
        S5: begin
            if (IN == 1) ST_nr = S1;
            else ST_nr = S2;
        end
        default: ST_nr = S0;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        ST_cr <= S0;
    end else begin
        ST_cr <= ST_nr;
    end
end

always @* begin
    if (RST) MATCH = 0;
    else if (ST_cr == S4 && IN == 1) MATCH = 1;
    else MATCH = 0;
end
endmodule
